    return parsed

def _index_entry(self, index_url: str, skill_name: str) -> Optional[dict]:
    parsed = self._parse_index(index_url)
    if not parsed:
        return None
    for entry in parsed["skills"]:
        if isinstance(entry, dict) and entry.get("name") == skill_name:
            return entry
    return None

