# ----- Reader / Poller Threads -----

def _reader_loop(self, session: ProcessSession):
    """Background thread: read stdout from a local Popen process."""
    first_chunk = True
    try:
        while True:
            chunk = session.process.stdout.read(4096)
            if not chunk:
                break
            if first_chunk:
                chunk = self._clean_shell_noise(chunk)
                first_chunk = False
            with session._lock:
                session.output_buffer += chunk
                if len(session.output_buffer) > session.max_output_chars:
                    session.output_buffer = session.output_buffer[-session.max_output_chars:]
    except Exception as e:
        logger.debug("Process stdout reader ended: %s", e)

    # Process exited
    try:
        session.process.wait(timeout=5)
    except Exception as e:
        logger.debug("Process wait timed out or failed: %s", e)
    session.exited = True
    session.exit_code = session.process.returncode
    self._move_to_finished(session)

def _env_poller_loop(

    self._move_to_finished(session)

def _env_poller_loop(
    self, session: ProcessSession, env: Any, log_path: str, pid_path: str
):
    """Background thread: poll a sandbox log file for non-local backends."""
    while not session.exited:
        time.sleep(2)  # Poll every 2 seconds
        try:
            # Read new output from the log file
            result = env.execute(f"cat {log_path} 2>/dev/null", timeout=10)
            new_output = result.get("output", "")
            if new_output:
                with session._lock:
                    session.output_buffer = new_output
                    if len(session.output_buffer) > session.max_output_chars:
                        session.output_buffer = session.output_buffer[-session.max_output_chars:]

            # Check if process is still running
            check = env.execute(
                f"kill -0 $(cat {pid_path} 2>/dev/null) 2>/dev/null; echo $?",
                timeout=5,
            )
            check_output = check.get("output", "").strip()
            if check_output and check_output.splitlines()[-1].strip() != "0":
                # Process has exited -- get exit code
                exit_result = env.execute(
                    f"wait $(cat {pid_path} 2>/dev/null) 2>/dev/null; echo $?",
                    timeout=5,
                )
                exit_str = exit_result.get("output", "").strip()
                try:
                    session.exit_code = int(exit_str.splitlines()[-1].strip())
                except (ValueError, IndexError):
                    session.exit_code = -1
                session.exited = True
                self._move_to_finished(session)
                return

        except Exception:
            # Environment might be gone (sandbox reaped, etc.)
            session.exited = True
            session.exit_code = -1
            self._move_to_finished(session)
            return

def _pty_reader_loop(self, session: ProcessSession):

            return

def _pty_reader_loop(self, session: ProcessSession):
    """Background thread: read output from a PTY process."""
    pty = session._pty
    try:
        while pty.isalive():
            try:
                chunk = pty.read(4096)
                if chunk:
                    # ptyprocess returns bytes
                    text = chunk if isinstance(chunk, str) else chunk.decode("utf-8", errors="replace")
                    with session._lock:
                        session.output_buffer += text
                        if len(session.output_buffer) > session.max_output_chars:
                            session.output_buffer = session.output_buffer[-session.max_output_chars:]
            except EOFError:
                break
            except Exception:
                break
    except Exception as e:
        logger.debug("PTY stdout reader ended: %s", e)

    # Process exited
    try:
        pty.wait()
    except Exception as e:
        logger.debug("PTY wait timed out or failed: %s", e)
    session.exited = True
    session.exit_code = pty.exitstatus if hasattr(pty, 'exitstatus') else -1
    self._move_to_finished(session)

def _move_to_finished(self, session: ProcessSession):

# ----- Query Methods -----

def get(self, session_id: str) -> Optional[ProcessSession]:
    """Get a session by ID (running or finished)."""
    with self._lock:
        session = self._running.get(session_id) or self._finished.get(session_id)
    return self._refresh_detached_session(session)

def poll(self, session_id: str) -> dict:

    return self._refresh_detached_session(session)

def poll(self, session_id: str) -> dict:
    """Check status and get new output for a background process."""
    from tools.ansi_strip import strip_ansi

    session = self.get(session_id)
    if session is None:
        return {"status": "not_found", "error": f"No process with ID {session_id}"}

    with session._lock:
        output_preview = strip_ansi(session.output_buffer[-1000:]) if session.output_buffer else ""

    result = {
        "session_id": session.id,
        "command": session.command,
        "status": "exited" if session.exited else "running",
        "pid": session.pid,
        "uptime_seconds": int(time.time() - session.started_at),
        "output_preview": output_preview,
    }
    if session.exited:
        result["exit_code"] = session.exit_code
    if session.detached:
        result["detached"] = True
        result["note"] = "Process recovered after restart -- output history unavailable"
    return result

