def _search_files(self, pattern: str, path: str, limit: int, offset: int) -> SearchResult:
    """Search for files by name pattern (glob-like)."""
    # Auto-prepend **/ for recursive search if not already present
    if not pattern.startswith('**/') and '/' not in pattern:
        search_pattern = pattern
    else:
        search_pattern = pattern.split('/')[-1]

    # Prefer ripgrep: respects .gitignore, excludes hidden dirs by
    # default, and has parallel directory traversal (~200x faster than
    # find on wide trees).  Mirrors _search_content which already uses rg.
    if self._has_command('rg'):
        return self._search_files_rg(search_pattern, path, limit, offset)

    # Fallback: find (slower, no .gitignore awareness)
    if not self._has_command('find'):
        return SearchResult(
            error="File search requires 'rg' (ripgrep) or 'find'. "
                  "Install ripgrep for best results: "
                  "https://github.com/BurntSushi/ripgrep#installation"
        )

    # Exclude hidden directories (matching ripgrep's default behavior).
    hidden_exclude = "-not -path '*/.*'"

    cmd = f"find {self._escape_shell_arg(path)} {hidden_exclude} -type f -name {self._escape_shell_arg(search_pattern)} " \
          f"-printf '%T@ %p\\n' 2>/dev/null | sort -rn | tail -n +{offset + 1} | head -n {limit}"

    result = self._exec(cmd, timeout=60)

    if not result.stdout.strip():
        # Try without -printf (BSD find compatibility -- macOS)
        cmd_simple = f"find {self._escape_shell_arg(path)} {hidden_exclude} -type f -name {self._escape_shell_arg(search_pattern)} " \
                    f"2>/dev/null | head -n {limit + offset} | tail -n +{offset + 1}"
        result = self._exec(cmd_simple, timeout=60)

    files = []
    for line in result.stdout.strip().split('\n'):
        if not line:
            continue
        parts = line.split(' ', 1)
        if len(parts) == 2 and parts[0].replace('.', '').isdigit():
            files.append(parts[1])
        else:
            files.append(line)

    return SearchResult(
        files=files,
        total_count=len(files)
    )

def _search_files_rg(self, pattern: str, path: str, limit: int, offset: int) -> SearchResult:

    )

def _search_content(self, pattern: str, path: str, file_glob: Optional[str],
                    limit: int, offset: int, output_mode: str, context: int) -> SearchResult:
    """Search for content inside files (grep-like)."""
    # Try ripgrep first (fast), fallback to grep (slower but works)
    if self._has_command('rg'):
        return self._search_with_rg(pattern, path, file_glob, limit, offset, 
                                    output_mode, context)
    elif self._has_command('grep'):
        return self._search_with_grep(pattern, path, file_glob, limit, offset,
                                      output_mode, context)
    else:
        # Neither rg nor grep available (Windows without Git Bash, etc.)
        return SearchResult(
            error="Content search requires ripgrep (rg) or grep. "
                  "Install ripgrep: https://github.com/BurntSushi/ripgrep#installation"
        )

def _search_with_rg(self, pattern: str, path: str, file_glob: Optional[str],

        )

def _search_with_rg(self, pattern: str, path: str, file_glob: Optional[str],
                    limit: int, offset: int, output_mode: str, context: int) -> SearchResult:
    """Search using ripgrep."""
    cmd_parts = ["rg", "--line-number", "--no-heading", "--with-filename"]

    # Add context if requested
    if context > 0:
        cmd_parts.extend(["-C", str(context)])

    # Add file glob filter (must be quoted to prevent shell expansion)
    if file_glob:
        cmd_parts.extend(["--glob", self._escape_shell_arg(file_glob)])

    # Output mode handling
    if output_mode == "files_only":
        cmd_parts.append("-l")  # Files only
    elif output_mode == "count":
        cmd_parts.append("-c")  # Count per file

    # Add pattern and path
    cmd_parts.append(self._escape_shell_arg(pattern))
    cmd_parts.append(self._escape_shell_arg(path))

    # Fetch extra rows so we can report the true total before slicing.
    # For context mode, rg emits separator lines ("--") between groups,
    # so we grab generously and filter in Python.
    fetch_limit = limit + offset + 200 if context > 0 else limit + offset
    cmd_parts.extend(["|", "head", "-n", str(fetch_limit)])

    cmd = " ".join(cmd_parts)
    result = self._exec(cmd, timeout=60)

    # rg exit codes: 0=matches found, 1=no matches, 2=error
    if result.exit_code == 2 and not result.stdout.strip():
        error_msg = result.stderr.strip() if hasattr(result, 'stderr') and result.stderr else "Search error"
        return SearchResult(error=f"Search failed: {error_msg}", total_count=0)

    # Parse results based on output mode
    if output_mode == "files_only":
        all_files = [f for f in result.stdout.strip().split('\n') if f]
        total = len(all_files)
        page = all_files[offset:offset + limit]
        return SearchResult(files=page, total_count=total)

    elif output_mode == "count":
        counts = {}
        for line in result.stdout.strip().split('\n'):
            if ':' in line:
                parts = line.rsplit(':', 1)
                if len(parts) == 2:
                    try:
                        counts[parts[0]] = int(parts[1])
                    except ValueError:
                        pass
        return SearchResult(counts=counts, total_count=sum(counts.values()))

    else:
        # Parse content matches and context lines.
        # rg match lines:   "file:lineno:content"  (colon separator)
        # rg context lines: "file-lineno-content"   (dash separator)
        # rg group seps:    "--"
        # Note: on Windows, paths contain drive letters (e.g. C:\path),
        # so naive split(":") breaks. Use regex to handle both platforms.
        _match_re = re.compile(r'^([A-Za-z]:)?(.*?):(\d+):(.*)$')
        _ctx_re = re.compile(r'^([A-Za-z]:)?(.*?)-(\d+)-(.*)$')
        matches = []
        for line in result.stdout.strip().split('\n'):
            if not line or line == "--":
                continue

            # Try match line first (colon-separated: file:line:content)
            m = _match_re.match(line)
            if m:
                matches.append(SearchMatch(
                    path=(m.group(1) or '') + m.group(2),
                    line_number=int(m.group(3)),
                    content=m.group(4)[:500]
                ))
                continue

            # Try context line (dash-separated: file-line-content)
            # Only attempt if context was requested to avoid false positives
            if context > 0:
                m = _ctx_re.match(line)
                if m:
                    matches.append(SearchMatch(
                        path=(m.group(1) or '') + m.group(2),
                        line_number=int(m.group(3)),
                        content=m.group(4)[:500]
                    ))

        total = len(matches)
        page = matches[offset:offset + limit]
        return SearchResult(
            matches=page,
            total_count=total,
            truncated=total > offset + limit
        )

def _search_with_grep(self, pattern: str, path: str, file_glob: Optional[str],

        )

def _search_with_grep(self, pattern: str, path: str, file_glob: Optional[str],
                      limit: int, offset: int, output_mode: str, context: int) -> SearchResult:
    """Fallback search using grep."""
    cmd_parts = ["grep", "-rnH"]  # -H forces filename even for single-file searches

    # Exclude hidden directories (matching ripgrep's default behavior).
    # This prevents searching inside .hub/index-cache/, .git/, etc.
    cmd_parts.append("--exclude-dir='.*'")

    # Add context if requested
    if context > 0:
        cmd_parts.extend(["-C", str(context)])

    # Add file pattern filter (must be quoted to prevent shell expansion)
    if file_glob:
        cmd_parts.extend(["--include", self._escape_shell_arg(file_glob)])

    # Output mode handling
    if output_mode == "files_only":
        cmd_parts.append("-l")
    elif output_mode == "count":
        cmd_parts.append("-c")

    # Add pattern and path
    cmd_parts.append(self._escape_shell_arg(pattern))
    cmd_parts.append(self._escape_shell_arg(path))

    # Fetch generously so we can compute total before slicing
    fetch_limit = limit + offset + (200 if context > 0 else 0)
    cmd_parts.extend(["|", "head", "-n", str(fetch_limit)])

    cmd = " ".join(cmd_parts)
    result = self._exec(cmd, timeout=60)

    # grep exit codes: 0=matches found, 1=no matches, 2=error
    if result.exit_code == 2 and not result.stdout.strip():
        error_msg = result.stderr.strip() if hasattr(result, 'stderr') and result.stderr else "Search error"
        return SearchResult(error=f"Search failed: {error_msg}", total_count=0)

    if output_mode == "files_only":
        all_files = [f for f in result.stdout.strip().split('\n') if f]
        total = len(all_files)
        page = all_files[offset:offset + limit]
        return SearchResult(files=page, total_count=total)

    elif output_mode == "count":
        counts = {}
        for line in result.stdout.strip().split('\n'):
            if ':' in line:
                parts = line.rsplit(':', 1)
                if len(parts) == 2:
                    try:
                        counts[parts[0]] = int(parts[1])
                    except ValueError:
                        pass
        return SearchResult(counts=counts, total_count=sum(counts.values()))

    else:
        # grep match lines:   "file:lineno:content" (colon)
        # grep context lines: "file-lineno-content"  (dash)
        # grep group seps:    "--"
        # Note: on Windows, paths contain drive letters (e.g. C:\path),
        # so naive split(":") breaks. Use regex to handle both platforms.
        _match_re = re.compile(r'^([A-Za-z]:)?(.*?):(\d+):(.*)$')
        _ctx_re = re.compile(r'^([A-Za-z]:)?(.*?)-(\d+)-(.*)$')
        matches = []
        for line in result.stdout.strip().split('\n'):
            if not line or line == "--":
                continue

            m = _match_re.match(line)
            if m:
                matches.append(SearchMatch(
                    path=(m.group(1) or '') + m.group(2),
                    line_number=int(m.group(3)),
                    content=m.group(4)[:500]
                ))
                continue

            if context > 0:
                m = _ctx_re.match(line)
                if m:
                    matches.append(SearchMatch(
                        path=(m.group(1) or '') + m.group(2),
                        line_number=int(m.group(3)),
                        content=m.group(4)[:500]
                    ))


        total = len(matches)
        page = matches[offset:offset + limit]
        return SearchResult(
            matches=page,
            total_count=total,
            truncated=total > offset + limit
        )

def _get_allowed() -> set[str]:
    """Get or create the allowed env vars set for the current context/session."""
    try:
        return _allowed_env_vars_var.get()
    except LookupError:
        val: set[str] = set()
        _allowed_env_vars_var.set(val)
        return val

def register_env_passthrough(var_names: Iterable[str]) -> None:
    """Register environment variable names as allowed in sandboxed environments.

    Typically called when a skill declares ``required_environment_variables``.
    """
    for name in var_names:
        name = name.strip()
        if name:
            _get_allowed().add(name)
            logger.debug("env passthrough: registered %s", name)

def _load_config_passthrough() -> frozenset[str]:
    """Load ``tools.env_passthrough`` from config.yaml (cached)."""
    global _config_passthrough
    if _config_passthrough is not None:
        return _config_passthrough

    result: set[str] = set()
    try:
        from hermes_cli.config import read_raw_config
        cfg = read_raw_config()
        passthrough = cfg.get("terminal", {}).get("env_passthrough")
        if isinstance(passthrough, list):
            for item in passthrough:
                if isinstance(item, str) and item.strip():
                    result.add(item.strip())
    except Exception as e:
        logger.debug("Could not read tools.env_passthrough from config: %s", e)

    _config_passthrough = frozenset(result)
    return _config_passthrough

def is_env_passthrough(var_name: str) -> bool:
    """Check whether *var_name* is allowed to pass through to sandboxes.

    Returns ``True`` if the variable was registered by a skill or listed in
    the user's ``tools.env_passthrough`` config.
    """
    if var_name in _get_allowed():
        return True
    return var_name in _load_config_passthrough()

def get_all_passthrough() -> frozenset[str]:
    """Return the union of skill-registered and config-based passthrough vars."""
    return frozenset(_get_allowed()) | _load_config_passthrough()

def clear_env_passthrough() -> None:
    """Reset the skill-scoped allowlist (e.g. on session reset)."""
    _get_allowed().clear()

def check_delegate_requirements() -> bool:
    """Delegation has no external requirements -- always available."""
    return True

def _resolve_workspace_hint(parent_agent) -> Optional[str]:
    """Best-effort local workspace hint for child prompts.

    We only inject a path when we have a concrete absolute directory. This avoids
    teaching subagents a fake container path while still helping them avoid
    guessing `/workspace/...` for local repo tasks.
    """
    candidates = [
        os.getenv("TERMINAL_CWD"),
        getattr(getattr(parent_agent, "_subdirectory_hints", None), "working_dir", None),
        getattr(parent_agent, "terminal_cwd", None),
        getattr(parent_agent, "cwd", None),
    ]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            text = os.path.abspath(os.path.expanduser(str(candidate)))
        except Exception:
            continue
        if os.path.isabs(text) and os.path.isdir(text):
            return text
    return None

def _strip_blocked_tools(toolsets: List[str]) -> List[str]:
    """Remove toolsets that contain only blocked tools."""
    blocked_toolset_names = {
        "delegation", "clarify", "memory", "code_execution",
    }
    return [t for t in toolsets if t not in blocked_toolset_names]

def _build_child_progress_callback(task_index: int, parent_agent, task_count: int = 1) -> Optional[callable]:
    """Build a callback that relays child agent tool calls to the parent display.

    Two display paths:
      CLI:     prints tree-view lines above the parent's delegation spinner
      Gateway: batches tool names and relays to parent's progress callback

    Returns None if no display mechanism is available, in which case the
    child agent runs with no progress callback (identical to current behavior).
    """
    spinner = getattr(parent_agent, '_delegate_spinner', None)
    parent_cb = getattr(parent_agent, 'tool_progress_callback', None)

    if not spinner and not parent_cb:
        return None  # No display → no callback → zero behavior change

    # Show 1-indexed prefix only in batch mode (multiple tasks)
    prefix = f"[{task_index + 1}] " if task_count > 1 else ""

    # Gateway: batch tool names, flush periodically
    _BATCH_SIZE = 5
    _batch: List[str] = []

    def _callback(event_type: str, tool_name: str = None, preview: str = None, args=None, **kwargs):
        # event_type is one of: "tool.started", "tool.completed",
        # "reasoning.available", "_thinking", "subagent_progress"

        # "_thinking" / reasoning events
        if event_type in ("_thinking", "reasoning.available"):
            text = preview or tool_name or ""
            if spinner:
                short = (text[:55] + "...") if len(text) > 55 else text
                try:
                    spinner.print_above(f" {prefix}├─  \"{short}\"")
                except Exception as e:
                    logger.debug("Spinner print_above failed: %s", e)
            # Don't relay thinking to gateway (too noisy for chat)
            return

        # tool.completed — no display needed here (spinner shows on started)
        if event_type == "tool.completed":
            return

        # tool.started — display and batch for parent relay
        if spinner:
            short = (preview[:35] + "...") if preview and len(preview) > 35 else (preview or "")
            from agent.display import get_tool_emoji
            emoji = get_tool_emoji(tool_name or "")
            line = f" {prefix}├─ {emoji} {tool_name}"
            if short:
                line += f"  \"{short}\""
            try:
                spinner.print_above(line)
            except Exception as e:
                logger.debug("Spinner print_above failed: %s", e)

        if parent_cb:
            _batch.append(tool_name or "")
            if len(_batch) >= _BATCH_SIZE:
                summary = ", ".join(_batch)
                try:
                    parent_cb("subagent_progress", f" {prefix}{summary}")
                except Exception as e:
                    logger.debug("Parent callback failed: %s", e)
                _batch.clear()

    def _flush():
        """Flush remaining batched tool names to gateway on completion."""
        if parent_cb and _batch:
            summary = ", ".join(_batch)
            try:
                parent_cb("subagent_progress", f" {prefix}{summary}")
            except Exception as e:
                logger.debug("Parent callback flush failed: %s", e)
            _batch.clear()

    _callback._flush = _flush
    return _callback

