def _default_export_ignore(root_dir: Path):
    """Return an *ignore* callable for :func:`shutil.copytree`.

    At the root level it excludes everything in ``_DEFAULT_EXPORT_EXCLUDE_ROOT``.
    At all levels it excludes ``__pycache__``, sockets, and temp files.
    """

    def _ignore(directory: str, contents: list) -> set:
        ignored: set = set()
        for entry in contents:
            # Universal exclusions (any depth)
            if entry == "__pycache__" or entry.endswith((".sock", ".tmp")):
                ignored.add(entry)
            # npm lockfiles can appear at root
            elif entry in ("package.json", "package-lock.json"):
                ignored.add(entry)
        # Root-level exclusions
        if Path(directory) == root_dir:
            ignored.update(c for c in contents if c in _DEFAULT_EXPORT_EXCLUDE_ROOT)
        return ignored

    return _ignore

"""

def _ignore(directory: str, contents: list) -> set:
    ignored: set = set()
    for entry in contents:
        # Universal exclusions (any depth)
        if entry == "__pycache__" or entry.endswith((".sock", ".tmp")):
            ignored.add(entry)
        # npm lockfiles can appear at root
        elif entry in ("package.json", "package-lock.json"):
            ignored.add(entry)
    # Root-level exclusions
    if Path(directory) == root_dir:
        ignored.update(c for c in contents if c in _DEFAULT_EXPORT_EXCLUDE_ROOT)
    return ignored

return _ignore

def _safe_extract_profile_archive(archive: Path, destination: Path) -> None:
    """Extract a profile archive without allowing path escapes or links."""
    import tarfile

    with tarfile.open(archive, "r:gz") as tf:
        for member in tf.getmembers():
            parts = _normalize_profile_archive_parts(member.name)
            target = destination.joinpath(*parts)

            if member.isdir():
                target.mkdir(parents=True, exist_ok=True)
                continue

            if not member.isfile():
                raise ValueError(
                    f"Unsupported archive member type: {member.name}"
                )

            target.parent.mkdir(parents=True, exist_ok=True)
            extracted = tf.extractfile(member)
            if extracted is None:
                raise ValueError(f"Cannot read archive member: {member.name}")

            with extracted, open(target, "wb") as dst:
                shutil.copyfileobj(extracted, dst)

            try:
                os.chmod(target, member.mode & 0o777)
            except OSError:
                pass

def import_profile(archive_path: str, name: Optional[str] = None) -> Path:
    """Import a profile from a tar.gz archive.

    If *name* is not given, infers it from the archive's top-level directory.
    Returns the imported profile directory.
    """
    import tarfile

    archive = Path(archive_path)
    if not archive.exists():
        raise FileNotFoundError(f"Archive not found: {archive}")

    # Peek at the archive to find the top-level directory name
    with tarfile.open(archive, "r:gz") as tf:
        top_dirs = {
            parts[0]
            for member in tf.getmembers()
            for parts in [_normalize_profile_archive_parts(member.name)]
            if len(parts) > 1 or member.isdir()
        }
        if not top_dirs:
            top_dirs = {
                _normalize_profile_archive_parts(member.name)[0]
                for member in tf.getmembers()
                if member.isdir()
            }

    inferred_name = name or (top_dirs.pop() if len(top_dirs) == 1 else None)
    if not inferred_name:
        raise ValueError(
            "Cannot determine profile name from archive. "
            "Specify it explicitly: hermes profile import <archive> --name <name>"
        )

    # Archives exported from the default profile have "default/" as top-level
    # dir.  Importing as "default" would target ~/.hermes itself — disallow
    # that and guide the user toward a named profile.
    if inferred_name == "default":
        raise ValueError(
            "Cannot import as 'default' — that is the built-in root profile (~/.hermes). "
            "Specify a different name: hermes profile import <archive> --name <name>"
        )

    validate_profile_name(inferred_name)
    profile_dir = get_profile_dir(inferred_name)
    if profile_dir.exists():
        raise FileExistsError(f"Profile '{inferred_name}' already exists at {profile_dir}")

    profiles_root = _get_profiles_root()
    profiles_root.mkdir(parents=True, exist_ok=True)

    _safe_extract_profile_archive(archive, profiles_root)

    # If the archive extracted under a different name, rename
    extracted = profiles_root / (top_dirs.pop() if top_dirs else inferred_name)
    if extracted != profile_dir and extracted.exists():
        extracted.rename(profile_dir)

    return profile_dir

def _sanitize_plugin_name(name: str, plugins_dir: Path) -> Path:
    """Validate a plugin name and return the safe target path inside *plugins_dir*.

    Raises ``ValueError`` if the name contains path-traversal sequences or would
    resolve outside the plugins directory.
    """
    if not name:
        raise ValueError("Plugin name must not be empty.")

    if name in (".", ".."):
        raise ValueError(
            f"Invalid plugin name '{name}': must not reference the plugins directory itself."
        )

    # Reject obvious traversal characters
    for bad in ("/", "\\", ".."):
        if bad in name:
            raise ValueError(f"Invalid plugin name '{name}': must not contain '{bad}'.")

    target = (plugins_dir / name).resolve()
    plugins_resolved = plugins_dir.resolve()

    if target == plugins_resolved:
        raise ValueError(
            f"Invalid plugin name '{name}': resolves to the plugins directory itself."
        )

    try:
        target.relative_to(plugins_resolved)
    except ValueError:
        raise ValueError(
            f"Invalid plugin name '{name}': resolves outside the plugins directory."
        )

    return target

def _read_manifest(plugin_dir: Path) -> dict:
    """Read plugin.yaml and return the parsed dict, or empty dict."""
    manifest_file = plugin_dir / "plugin.yaml"
    if not manifest_file.exists():
        return {}
    try:
        import yaml

        with open(manifest_file) as f:
            return yaml.safe_load(f) or {}
    except Exception as e:
        logger.warning("Failed to read plugin.yaml in %s: %s", plugin_dir, e)
        return {}

def _copy_example_files(plugin_dir: Path, console) -> None:
    """Copy any .example files to their real names if they don't already exist.

    For example, ``config.yaml.example`` becomes ``config.yaml``.
    Skips files that already exist to avoid overwriting user config on reinstall.
    """
    for example_file in plugin_dir.glob("*.example"):
        real_name = example_file.stem  # e.g. "config.yaml" from "config.yaml.example"
        real_path = plugin_dir / real_name
        if not real_path.exists():
            try:
                shutil.copy2(example_file, real_path)
                console.print(
                    f"[dim]  Created {real_name} from {example_file.name}[/dim]"
                )
            except OSError as e:
                console.print(
                    f"[yellow]Warning:[/yellow] Failed to copy {example_file.name}: {e}"
                )

def _get_disabled_set() -> set:
    """Read the disabled plugins set from config.yaml."""
    try:
        from hermes_cli.config import load_config
        config = load_config()
        disabled = config.get("plugins", {}).get("disabled", [])
        return set(disabled) if isinstance(disabled, list) else set()
    except Exception:
        return set()

def _save_disabled_set(disabled: set) -> None:
    """Write the disabled plugins list to config.yaml."""
    from hermes_cli.config import load_config, save_config
    config = load_config()
    if "plugins" not in config:
        config["plugins"] = {}
    config["plugins"]["disabled"] = sorted(disabled)
    save_config(config)

def plugins_command(args) -> None:
    """Dispatch hermes plugins subcommands."""
    action = getattr(args, "plugins_action", None)

    if action == "install":
        cmd_install(args.identifier, force=getattr(args, "force", False))
    elif action == "update":
        cmd_update(args.name)
    elif action in ("remove", "rm", "uninstall"):
        cmd_remove(args.name)
    elif action == "enable":
        cmd_enable(args.name)
    elif action == "disable":
        cmd_disable(args.name)
    elif action in ("list", "ls"):
        cmd_list()
    elif action is None:
        cmd_toggle()
    else:
        from rich.console import Console

        Console().print(f"[red]Unknown plugins action: {action}[/red]")
        sys.exit(1)

def _env_enabled(name: str) -> bool:
    """Return True when an env var is set to a truthy opt-in value."""
    return env_var_enabled(name)

def _get_disabled_plugins() -> set:
    """Read the disabled plugins list from config.yaml."""
    try:
        from hermes_cli.config import load_config
        config = load_config()
        disabled = config.get("plugins", {}).get("disabled", [])
        return set(disabled) if isinstance(disabled, list) else set()
    except Exception:
        return set()

"""Central manager that discovers, loads, and invokes plugins."""

def __init__(self) -> None:
    self._plugins: Dict[str, LoadedPlugin] = {}
    self._hooks: Dict[str, List[Callable]] = {}
    self._plugin_tool_names: Set[str] = set()
    self._cli_commands: Dict[str, dict] = {}
    self._discovered: bool = False
    self._cli_ref = None  # Set by CLI after plugin discovery

# -----------------------------------------------------------------------

# -----------------------------------------------------------------------

def _scan_directory(self, path: Path, source: str) -> List[PluginManifest]:
    """Read ``plugin.yaml`` manifests from subdirectories of *path*."""
    manifests: List[PluginManifest] = []
    if not path.is_dir():
        return manifests

    for child in sorted(path.iterdir()):
        if not child.is_dir():
            continue
        manifest_file = child / "plugin.yaml"
        if not manifest_file.exists():
            manifest_file = child / "plugin.yml"
        if not manifest_file.exists():
            logger.debug("Skipping %s (no plugin.yaml)", child)
            continue

        try:
            if yaml is None:
                logger.warning("PyYAML not installed – cannot load %s", manifest_file)
                continue
            data = yaml.safe_load(manifest_file.read_text()) or {}
            manifest = PluginManifest(
                name=data.get("name", child.name),
                version=str(data.get("version", "")),
                description=data.get("description", ""),
                author=data.get("author", ""),
                requires_env=data.get("requires_env", []),
                provides_tools=data.get("provides_tools", []),
                provides_hooks=data.get("provides_hooks", []),
                source=source,
                path=str(child),
            )
            manifests.append(manifest)
        except Exception as exc:
            logger.warning("Failed to parse %s: %s", manifest_file, exc)

    return manifests

# -----------------------------------------------------------------------

# -----------------------------------------------------------------------

def _scan_entry_points(self) -> List[PluginManifest]:
    """Check ``importlib.metadata`` for pip-installed plugins."""
    manifests: List[PluginManifest] = []
    try:
        eps = importlib.metadata.entry_points()
        # Python 3.12+ returns a SelectableGroups; earlier returns dict
        if hasattr(eps, "select"):
            group_eps = eps.select(group=ENTRY_POINTS_GROUP)
        elif isinstance(eps, dict):
            group_eps = eps.get(ENTRY_POINTS_GROUP, [])
        else:
            group_eps = [ep for ep in eps if ep.group == ENTRY_POINTS_GROUP]

        for ep in group_eps:
            manifest = PluginManifest(
                name=ep.name,
                source="entrypoint",
                path=ep.value,
            )
            manifests.append(manifest)
    except Exception as exc:
        logger.debug("Entry-point scan failed: %s", exc)

    return manifests

# -----------------------------------------------------------------------

# -----------------------------------------------------------------------

def _load_plugin(self, manifest: PluginManifest) -> None:
    """Import a plugin module and call its ``register(ctx)`` function."""
    loaded = LoadedPlugin(manifest=manifest)

    try:
        if manifest.source in ("user", "project"):
            module = self._load_directory_module(manifest)
        else:
            module = self._load_entrypoint_module(manifest)

        loaded.module = module

        # Call register()
        register_fn = getattr(module, "register", None)
        if register_fn is None:
            loaded.error = "no register() function"
            logger.warning("Plugin '%s' has no register() function", manifest.name)
        else:
            ctx = PluginContext(manifest, self)
            register_fn(ctx)
            loaded.tools_registered = [
                t for t in self._plugin_tool_names
                if t not in {
                    n
                    for name, p in self._plugins.items()
                    for n in p.tools_registered
                }
            ]
            loaded.hooks_registered = list(
                {
                    h
                    for h, cbs in self._hooks.items()
                    if cbs  # non-empty
                }
                - {
                    h
                    for name, p in self._plugins.items()
                    for h in p.hooks_registered
                }
            )
            loaded.enabled = True

    except Exception as exc:
        loaded.error = str(exc)
        logger.warning("Failed to load plugin '%s': %s", manifest.name, exc)

    self._plugins[manifest.name] = loaded

def _load_directory_module(self, manifest: PluginManifest) -> types.ModuleType:

    return module

def _load_entrypoint_module(self, manifest: PluginManifest) -> types.ModuleType:
    """Load a pip-installed plugin via its entry-point reference."""
    eps = importlib.metadata.entry_points()
    if hasattr(eps, "select"):
        group_eps = eps.select(group=ENTRY_POINTS_GROUP)
    elif isinstance(eps, dict):
        group_eps = eps.get(ENTRY_POINTS_GROUP, [])
    else:
        group_eps = [ep for ep in eps if ep.group == ENTRY_POINTS_GROUP]

    for ep in group_eps:
        if ep.name == manifest.name:
            return ep.load()

    raise ImportError(
        f"Entry point '{manifest.name}' not found in group '{ENTRY_POINTS_GROUP}'"
    )

