def _label(mid):
    if has_pricing:
        inp, out, cache = _price_cache.get(mid, ("", "", ""))
        price_part = f" {inp:>{price_col}}  {out:>{price_col}}"
        if has_cache:
            price_part += f"  {cache:>{cache_col}}"
        base = f"{mid:<{name_col}}{price_part}"
