def _save_model_choice(model_id: str) -> None:
    """Save the selected model to config.yaml (single source of truth).

    The model is stored in config.yaml only — NOT in .env.  This avoids
    conflicts in multi-agent setups where env vars would stomp each other.
    """
    from hermes_cli.config import save_config, load_config

    config = load_config()
    # Always use dict format so provider/base_url can be stored alongside
    if isinstance(config.get("model"), dict):
        config["model"]["default"] = model_id
    else:
        config["model"] = {"default": model_id}
    save_config(config)

def logout_command(args) -> None:
    """Clear auth state for a provider."""
    provider_id = getattr(args, "provider", None)

    if provider_id and provider_id not in PROVIDER_REGISTRY:
        print(f"Unknown provider: {provider_id}")
        raise SystemExit(1)

    active = get_active_provider()
    target = provider_id or active

    if not target:
        print("No provider is currently logged in.")
        return

    provider_name = PROVIDER_REGISTRY[target].name if target in PROVIDER_REGISTRY else target

    if clear_provider_auth(target):
        _reset_config_provider()
        print(f"Logged out of {provider_name}.")
        if os.getenv("OPENROUTER_API_KEY"):
            print("Hermes will use OpenRouter for inference.")
        else:
            print("Run `hermes model` or configure an API key to use Hermes.")
    else:
        print(f"No auth state found for {provider_name}.")

@property
def already_sent(self) -> bool:
    """True if at least one message was sent/edited — signals the base
    adapter to skip re-sending the final response."""
    return self._already_sent

def on_delta(self, text: str) -> None:

    return self._already_sent

def on_delta(self, text: str) -> None:
    """Thread-safe callback — called from the agent's worker thread.

    When *text* is ``None``, signals a tool boundary: the current message
    is finalized and subsequent text will be sent as a new message so it
    appears below any tool-progress messages the gateway sent in between.
    """
    if text:
        self._queue.put(text)
    elif text is None:
        self._queue.put(_NEW_SEGMENT)

def finish(self) -> None:

    return cleaned.rstrip()

def _visible_prefix(self) -> str:
    """Return the visible text already shown in the streamed message."""
    prefix = self._last_sent_text or ""
    if self.cfg.cursor and prefix.endswith(self.cfg.cursor):
        prefix = prefix[:-len(self.cfg.cursor)]
    return self._clean_for_display(prefix)

def _continuation_text(self, final_text: str) -> str:

    return self._clean_for_display(prefix)

def _continuation_text(self, final_text: str) -> str:
    """Return only the part of final_text the user has not already seen."""
    prefix = self._fallback_prefix or self._visible_prefix()
    if prefix and final_text.startswith(prefix):
        return final_text[len(prefix):].lstrip()
    return final_text

@staticmethod

@staticmethod
def _split_text_chunks(text: str, limit: int) -> list[str]:
    """Split text into reasonably sized chunks for fallback sends."""
    if len(text) <= limit:
        return [text]
    chunks: list[str] = []
    remaining = text
    while len(remaining) > limit:
        split_at = remaining.rfind("\n", 0, limit)
        if split_at < limit // 2:
            split_at = limit
        chunks.append(remaining[:split_at])
        remaining = remaining[split_at:].lstrip("\n")
    if remaining:
        chunks.append(remaining)
    return chunks

