        import yaml as _y
        cfg_path = _hermes_home / "config.yaml"
        if cfg_path.exists():
            with open(cfg_path, encoding="utf-8") as _f:
                cfg = _y.safe_load(_f) or {}
            return cfg.get("provider_routing", {}) or {}
    except Exception:
