async def _handle_reasoning_command(self, event: MessageEvent) -> str:
    """Handle /reasoning command — manage reasoning effort and display toggle.

    Usage:
        /reasoning              Show current effort level and display state
        /reasoning <level>      Set reasoning effort (none, low, medium, high, xhigh)
        /reasoning show|on      Show model reasoning in responses
        /reasoning hide|off     Hide model reasoning from responses
    """
    import yaml

    args = event.get_command_args().strip().lower()
    config_path = _hermes_home / "config.yaml"
    self._reasoning_config = self._load_reasoning_config()
    self._show_reasoning = self._load_show_reasoning()

    def _save_config_key(key_path: str, value):
        """Save a dot-separated key to config.yaml."""
        try:
            user_config = {}
            if config_path.exists():
                with open(config_path, encoding="utf-8") as f:
                    user_config = yaml.safe_load(f) or {}
            keys = key_path.split(".")
            current = user_config
            for k in keys[:-1]:
                if k not in current or not isinstance(current[k], dict):
                    current[k] = {}
                current = current[k]
            current[keys[-1]] = value
            atomic_yaml_write(config_path, user_config)
            return True
        except Exception as e:
            logger.error("Failed to save config key %s: %s", key_path, e)
            return False

    if not args:
        # Show current state
        rc = self._reasoning_config
        if rc is None:
            level = "medium (default)"
        elif rc.get("enabled") is False:
            level = "none (disabled)"
        else:
            level = rc.get("effort", "medium")
        display_state = "on ✓" if self._show_reasoning else "off"
        return (
            " **Reasoning Settings**\n\n"
            f"**Effort:** `{level}`\n"
            f"**Display:** {display_state}\n\n"
            "_Usage:_ `/reasoning <none|low|medium|high|xhigh|show|hide>`"
        )

    # Display toggle
    if args in ("show", "on"):
        self._show_reasoning = True
        _save_config_key("display.show_reasoning", True)
        return " ✓ Reasoning display: **ON**\nModel thinking will be shown before each response."

    if args in ("hide", "off"):
        self._show_reasoning = False
        _save_config_key("display.show_reasoning", False)
        return " ✓ Reasoning display: **OFF**"

    # Effort level change
    effort = args.strip()
    if effort == "none":
        parsed = {"enabled": False}
    elif effort in ("xhigh", "high", "medium", "low", "minimal"):
        parsed = {"enabled": True, "effort": effort}
    else:
        return (
            f"⚠️ Unknown argument: `{effort}`\n\n"
            "**Valid levels:** none, low, minimal, medium, high, xhigh\n"
            "**Display:** show, hide"
        )

    self._reasoning_config = parsed
    if _save_config_key("agent.reasoning_effort", effort):
        return f" ✓ Reasoning effort set to `{effort}` (saved to config)\n_(takes effect on next message)_"
    else:
        return f" ✓ Reasoning effort set to `{effort}` (this session only)"

