@classmethod
def parse(cls, target: str, origin: Optional[SessionSource] = None) -> "DeliveryTarget":
    """
    Parse a delivery target string.

    Formats:
    - "origin" → back to source
    - "local" → local files only
    - "telegram" → Telegram home channel
    - "telegram:123456" → specific Telegram chat
    """
    target = target.strip().lower()

    if target == "origin":
        if origin:
            return cls(
                platform=origin.platform,
                chat_id=origin.chat_id,
                thread_id=origin.thread_id,
                is_origin=True,
            )
        else:
            # Fallback to local if no origin
            return cls(platform=Platform.LOCAL, is_origin=True)

    if target == "local":
        return cls(platform=Platform.LOCAL)

    # Check for platform:chat_id or platform:chat_id:thread_id format
    if ":" in target:
        parts = target.split(":", 2)
        platform_str = parts[0]
        chat_id = parts[1] if len(parts) > 1 else None
        thread_id = parts[2] if len(parts) > 2 else None
        try:
            platform = Platform(platform_str)
            return cls(platform=platform, chat_id=chat_id, thread_id=thread_id, is_explicit=True)
        except ValueError:
            # Unknown platform, treat as local
            return cls(platform=Platform.LOCAL)

    # Just a platform name (use home channel)
    try:
        platform = Platform(target)
        return cls(platform=platform)
    except ValueError:
        # Unknown platform, treat as local
        return cls(platform=Platform.LOCAL)

def to_string(self) -> str:

        return cls(platform=Platform.LOCAL)

def to_string(self) -> str:
    """Convert back to string format."""
    if self.is_origin:
        return "origin"
    if self.platform == Platform.LOCAL:
        return "local"
    if self.chat_id and self.thread_id:
        return f"{self.platform.value}:{self.chat_id}:{self.thread_id}"
    if self.chat_id:
        return f"{self.platform.value}:{self.chat_id}"
    return self.platform.value

    return targets

async def deliver(
    self,
    content: str,
    targets: List[DeliveryTarget],
    job_id: Optional[str] = None,
    job_name: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None
) -> Dict[str, Any]:
    """
    Deliver content to all specified targets.

    Args:
        content: The message/output to deliver
        targets: List of delivery targets
        job_id: Optional job ID (for cron jobs)
        job_name: Optional job name
        metadata: Additional metadata to include

    Returns:
        Dict with delivery results per target
    """
    results = {}

    for target in targets:
        try:
            if target.platform == Platform.LOCAL:
                result = self._deliver_local(content, job_id, job_name, metadata)
            else:
                result = await self._deliver_to_platform(target, content, metadata)

            results[target.to_string()] = {
                "success": True,
                "result": result
            }
        except Exception as e:
            results[target.to_string()] = {
                "success": False,
                "error": str(e)
            }

    return results

def _deliver_local(

    return results

def _deliver_local(
    self,
    content: str,
    job_id: Optional[str],
    job_name: Optional[str],
    metadata: Optional[Dict[str, Any]]
) -> Dict[str, Any]:
    """Save content to local files."""
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

    if job_id:
        output_path = self.output_dir / job_id / f"{timestamp}.md"
    else:
        output_path = self.output_dir / "misc" / f"{timestamp}.md"

    output_path.parent.mkdir(parents=True, exist_ok=True)

    # Build the output document
    lines = []
    if job_name:
        lines.append(f"# {job_name}")
    else:
        lines.append("# Delivery Output")

    lines.append("")
    lines.append(f"**Timestamp:** {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")

    if job_id:
        lines.append(f"**Job ID:** {job_id}")

    if metadata:
        for key, value in metadata.items():
            lines.append(f"**{key}:** {value}")

    lines.append("")
    lines.append("---")
    lines.append("")
    lines.append(content)

    output_path.write_text("\n".join(lines))

    return {
        "path": str(output_path),
        "timestamp": timestamp
    }

