def close(self) -> None:
    proc: subprocess.Popen[str] | None
    with self._active_process_lock:
        proc = self._active_process
        self._active_process = None
    self.is_closed = True
    if proc is None:
        return
    try:
        proc.terminate()
        proc.wait(timeout=2)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass

