// --- Noise Overlay (ported from hermes-chat NoiseOverlay) ---
function initNoiseOverlay() {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  if (typeof THREE === "undefined") return;

  const canvas = document.getElementById("noise-overlay");
  if (!canvas) return;

  const vertexShader = `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `;

  const fragmentShader = `
        uniform vec2 uRes;
        uniform float uDpr, uSize, uDensity, uOpacity;
        uniform vec3 uColor;
        varying vec2 vUv;

        float hash(vec2 p) {
            vec3 p3 = fract(vec3(p.xyx) * 0.1031);
            p3 += dot(p3, p3.yzx + 33.33);
            return fract((p3.x + p3.y) * p3.z);
        }

        void main() {
            float n = hash(floor(vUv * uRes / (uSize * uDpr)));
            gl_FragColor = vec4(uColor, step(1.0 - uDensity, n)) * uOpacity;
        }
    `;

  function hexToVec3(hex) {
    const c = hex.replace("#", "");
    return new THREE.Vector3(
      parseInt(c.substring(0, 2), 16) / 255,
      parseInt(c.substring(2, 4), 16) / 255,
      parseInt(c.substring(4, 6), 16) / 255,
    );
  }

  const renderer = new THREE.WebGLRenderer({
    alpha: true,
    canvas,
    premultipliedAlpha: false,
  });
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const geo = new THREE.PlaneGeometry(2, 2);

  const mat = new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    transparent: true,
    uniforms: {
      uColor: { value: hexToVec3("#8090BB") },
      uDensity: { value: 0.1 },
      uDpr: { value: 1 },
      uOpacity: { value: 0.4 },
      uRes: { value: new THREE.Vector2() },
      uSize: { value: 1.0 },
    },
  });

  scene.add(new THREE.Mesh(geo, mat));

  function resize() {
    const dpr = window.devicePixelRatio;
    const w = window.innerWidth;
    const h = window.innerHeight;
    renderer.setSize(w, h);
    renderer.setPixelRatio(dpr);
    mat.uniforms.uRes.value.set(w * dpr, h * dpr);
    mat.uniforms.uDpr.value = dpr;
  }

  resize();
  window.addEventListener("resize", resize);

  function loop() {
    requestAnimationFrame(loop);
    renderer.render(scene, camera);
  }
  loop();
}

