import re

def parse_tokens(s):
    m = re.search(r"~([\d.]+)k?\s+tokens", s)
    if not m:
        return 0
    val = float(m.group(1))
    if "k" in s[m.start():m.end()]:
        val *= 1000
    return val

web_tok = parse_tokens(web_only)

ts_keys = [ts_key for ts_key, _, _ in CONFIGURABLE_TOOLSETS]

def status_fn(chosen: set) -> str:
    all_tools: set = set()
    for idx in chosen:
        all_tools.update(resolve_toolset(ts_keys[idx]))
    total = sum(tokens.get(name, 0) for name in all_tools)
    if total >= 1000:
        return f"Est. tool context: ~{total / 1000:.1f}k tokens"
    return f"Est. tool context: ~{total} tokens"

result = status_fn(set())

@pytest.mark.parametrize("filepath", _CLI_MODULES)
def test_all_subprocess_run_calls_have_timeout(filepath):
    """Every subprocess.run() call in CLI modules must specify a timeout."""
    if not Path(filepath).exists():
        pytest.skip(f"{filepath} not found")
    calls = _subprocess_run_calls(filepath)
    missing = [c for c in calls if not c["has_timeout"]]
    assert not missing, (
        f"{filepath} has subprocess.run() without timeout at "
        f"line(s): {[c['line'] for c in missing]}"
    )

