"""Return pre-canned sessions, then None once exhausted."""

def __init__(self, sessions):
    self._sessions = list(sessions)

def get(self, session_id):

    self._sessions = list(sessions)

def get(self, session_id):
    if self._sessions:
        return self._sessions.pop(0)
    return None

