                            {"tag": "text", "text": " "},
                            {"tag": "text", "text": "Italic", "style": {"italic": True}},
                            {"tag": "text", "text": " "},
                            {"tag": "text", "text": "Code", "style": {"code": True}},
                        ],
                        [{"tag": "text", "text": "line1"}, {"tag": "br"}, {"tag": "text", "text": "line2"}],
