def _redact_phone(phone: str) -> str:
    """Redact a phone number for logging: +15551234567 -> +155****4567."""
    if not phone:
        return "<none>"
    if len(phone) <= 8:
        return phone[:2] + "****" + phone[-2:] if len(phone) > 4 else "****"
    return phone[:4] + "****" + phone[-4:]

def _parse_comma_list(value: str) -> List[str]:
    """Split a comma-separated string into a list, stripping whitespace."""
    return [v.strip() for v in value.split(",") if v.strip()]

def _guess_extension(data: bytes) -> str:
    """Guess file extension from magic bytes."""
    if data[:4] == b"\x89PNG":
        return ".png"
    if data[:2] == b"\xff\xd8":
        return ".jpg"
    if data[:4] == b"GIF8":
        return ".gif"
    if len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return ".webp"
    if data[:4] == b"%PDF":
        return ".pdf"
    if len(data) >= 8 and data[4:8] == b"ftyp":
        return ".mp4"
    if data[:4] == b"OggS":
        return ".ogg"
    if len(data) >= 2 and data[0] == 0xFF and (data[1] & 0xE0) == 0xE0:
        return ".mp3"
    if data[:2] == b"PK":
        return ".zip"
    return ".bin"

def _ext_to_mime(ext: str) -> str:
    """Map file extension to MIME type."""
    return _EXT_TO_MIME.get(ext.lower(), "application/octet-stream")

def check_signal_requirements() -> bool:
    """Check if Signal is configured (has URL and account)."""
    return bool(os.getenv("SIGNAL_HTTP_URL") and os.getenv("SIGNAL_ACCOUNT"))

    return True

async def disconnect(self) -> None:
    """Stop SSE listener and clean up."""
    self._running = False

    if self._sse_task:
        self._sse_task.cancel()
        try:
            await self._sse_task
        except asyncio.CancelledError:
            pass

    if self._health_monitor_task:
        self._health_monitor_task.cancel()
        try:
            await self._health_monitor_task
        except asyncio.CancelledError:
            pass

    # Cancel all typing tasks
    for task in self._typing_tasks.values():
        task.cancel()
    self._typing_tasks.clear()

    if self.client:
        await self.client.aclose()
        self.client = None

    if self._phone_lock_identity:
        try:
            from gateway.status import release_scoped_lock
            release_scoped_lock("signal-phone", self._phone_lock_identity)
        except Exception as e:
            logger.warning("Signal: Error releasing phone lock: %s", e, exc_info=True)
        self._phone_lock_identity = None

    logger.info("Signal: disconnected")

