async def send(
    self,
    chat_id: str,
    content: str,
    reply_to: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
) -> SendResult:
    """Send a notification via HA REST API (persistent_notification.create).

    Uses the REST API instead of WebSocket to avoid a race condition
    with the event listener loop that reads from the same WS connection.
    """
    url = f"{self._hass_url}/api/services/persistent_notification/create"
    headers = {
        "Authorization": f"Bearer {self._hass_token}",
        "Content-Type": "application/json",
    }
    payload = {
        "title": "Hermes Agent",
        "message": content[:self.MAX_MESSAGE_LENGTH],
    }

    try:
        if self._rest_session:
            async with self._rest_session.post(
                url,
                headers=headers,
                json=payload,
                timeout=aiohttp.ClientTimeout(total=10),
            ) as resp:
                if resp.status < 300:
                    return SendResult(success=True, message_id=uuid.uuid4().hex[:12])
                else:
                    body = await resp.text()
                    return SendResult(success=False, error=f"HTTP {resp.status}: {body}")
        else:
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    url,
                    headers=headers,
                    json=payload,
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    if resp.status < 300:
                        return SendResult(success=True, message_id=uuid.uuid4().hex[:12])
                    else:
                        body = await resp.text()
                        return SendResult(success=False, error=f"HTTP {resp.status}: {body}")

    except asyncio.TimeoutError:
        return SendResult(success=False, error="Timeout sending notification to HA")
    except Exception as e:
        return SendResult(success=False, error=str(e))

