    chat_id: str,
    message_guid: str,
    reaction: str,
    part_index: int = 0,
) -> SendResult:
    """Send a tapback reaction (requires Private API helper)."""
    if not self._private_api_enabled or not self._helper_connected:
        return SendResult(
