def _headers(self, path: str) -> dict:
    token = self.api_key.replace("Bearer ", "").strip()
    h = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-sdk-runtime": "hermes-plugin",
