def _loop(self) -> None:
    while True:
        try:
            item = self._q.get(timeout=5)
            if item is _ASYNC_SHUTDOWN:
                break
            self._flush_row(*item)
        except queue.Empty:
            continue
        except Exception as exc:
            logger.error("RetainDB writer error: %s", exc)

