@staticmethod
def _unwrap_results(response: Any) -> list:
    """Normalize Mem0 API response — v2 wraps results in {"results": [...]}."""
    if isinstance(response, dict):
        return response.get("results", [])
    if isinstance(response, list):
        return response
    return []

