def shutdown(self) -> None:
    for t in (self._prefetch_thread, self._sync_thread):
        if t and t.is_alive():
            t.join(timeout=5.0)
    # Flush any remaining messages
    if self._manager:
        try:
            self._manager.flush_all()
        except Exception:
            pass

