    w = word.lower()
    vowels = 'aeiou'
    if w[0] in vowels:
        return w + 'yay'
    idx = next((i for i, c in enumerate(w) if c in vowels), -1)
    if idx > 0:
        return w[idx:] + w[:idx] + 'ay'
    return w + 'ay'

